const fs=require("fs");
const path=require("path");
const {execFileSync,execSync}=require("child_process");

const root=process.cwd();
const P=(...parts)=>path.join(root,...parts);
const fail=(m)=>{console.error("\nERROR: "+m);process.exit(1)};

let branch="";
try {
  branch=execFileSync("git",["branch","--show-current"],{cwd:root,encoding:"utf8"}).trim();
} catch {
  fail("تعذر قراءة فرع Git.");
}

if(branch!=="v2-dev"){
  fail("شغّل الملف على فرع v2-dev فقط. الفرع الحالي: "+branch);
}

const appPath=P("src","App.css");
const platformPath=P("src","platform.css");

if(!fs.existsSync(appPath)||!fs.existsSync(platformPath)){
  fail("لم أجد src/App.css أو src/platform.css.");
}

const backupSuffix=".bak-phase2l-claude-ui";
for(const file of [appPath,platformPath]){
  const backup=file+backupSuffix;
  if(!fs.existsSync(backup)){
    fs.copyFileSync(file,backup);
    console.log("Backup:",path.relative(root,backup));
  }
}

const appCss=Buffer.from("","base64").toString("utf8");
const platformCss=Buffer.from("","base64").toString("utf8");

function validateCss(name,content){
  const opens=(content.match(/\{/g)||[]).length;
  const closes=(content.match(/\}/g)||[]).length;
  if(opens!==closes) fail(name+" غير متوازن في { }.");
  const unsafe=["@import","javascript:","expression(","behavior:"];
  for(const token of unsafe){
    if(content.toLowerCase().includes(token.toLowerCase())){
      fail(name+" يحتوي على تعبير غير متوقع: "+token);
    }
  }
}

validateCss("App.css",appCss);
validateCss("platform.css",platformCss);

if(!platformCss.includes("EXAMBANK_2_PHASE_J_CHARTJS")){
  fail("لم أجد تنسيقات Phase J / Chart.js داخل platform.css، لذلك أوقفت التطبيق للحماية.");
}

fs.writeFileSync(appPath,appCss,"utf8");
fs.writeFileSync(platformPath,platformCss,"utf8");

console.log("\nApplied Claude UI:");
console.log("  src/App.css");
console.log("  src/platform.css");
console.log("No TSX, API, package.json or backend files were changed.");

console.log("\nRunning npm build...\n");
try {
  execSync("npm run build",{cwd:root,stdio:"inherit",shell:true});
} catch {
  console.error("\nBuild failed. Restoring CSS backups...");
  fs.copyFileSync(appPath+backupSuffix,appPath);
  fs.copyFileSync(platformPath+backupSuffix,platformPath);
  console.error("Original CSS restored.");
  process.exit(1);
}

console.log("\nPhase 2.0L Claude Professional CSS installed successfully.");
console.log("Sidebar + softened professional UI applied through CSS only.");
console.log("\nReview locally before git commit/push.");
